import{_ as i,o as a,c as n,aj as e}from"./chunks/framework.BdtAaXf2.js";const t="/assets/image-20260709231150449.BaEBvVZn.png",l="/assets/arch-overview._IT5oASw.png",p="/assets/dag-review.BYyIH2U1.png",h="/assets/image-20260714200405991.D5ORYyvY.png",r="/assets/risk-matrix.CpH9gkPI.png",k="/assets/image-20260714200451930.DxZ5atR-.png",o="/assets/dashboard.BOmnhiAU.png",b=JSON.parse('{"title":"合同智能审查与风险追踪：关键条款识别 + 风险标注 + 修改建议","description":"","frontmatter":{},"headers":[],"relativePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/03-法律合规场景/合同智能审查与风险追踪：关键条款识别+风险标注+修改建议.md","filePath":"AI人工智能/jiuwenswarm-垂直行业技术文章/03-法律合规场景/合同智能审查与风险追踪：关键条款识别+风险标注+修改建议.md","lastUpdated":1784030769000,"__rawMarkdown":"# 合同智能审查与风险追踪：关键条款识别 + 风险标注 + 修改建议\\n\\n> 一份采购合同动辄几十页、上百条条款，法务要逐条找\\"坑\\"：责任是不是没上限、付款条件是不是太苛刻、知识产权是不是全归对方、数据合规条款有没有漏。靠人逐条审，慢、易漏、还难把经验沉淀下来。本文看 **JiuwenSwarm** 如何把合同审查变成一支**并行评审的 Agent 团队**：自动解析合同、并行识别关键条款、对照条款库做风险分级标注、给出条款级修改建议——而且每审一份合同，\\"踩过的坑\\"就自动沉淀进条款库，越审越准。\\n\\n## 目录\\n\\n- [合同审查的三道老难题](#合同审查的三道老难题)\\n- [JiuwenSwarm 凭什么能“审合同”](#jiuwenswarm-凭什么能审合同)\\n- [并行评审的合同审查团队](#并行评审的合同审查团队)\\n- [让关键条款自己浮出来](#让关键条款自己浮出来)\\n  - [审查的工作流长什么样](#审查的工作流长什么样)\\n- [风险怎么标注、怎么分级](#风险怎么标注怎么分级)\\n- [修改建议是怎么生成的](#修改建议是怎么生成的)\\n- [PDF 和扫描件怎么进来](#pdf-和扫描件怎么进来)\\n- [合同审查台长什么样](#合同审查台长什么样)\\n- [落地建议与总结](#落地建议与总结)\\n- [相关引用](#相关引用)\\n\\n---\\n\\n## 合同审查的三道老难题\\n\\n![](./assets/image-20260709231150449.png)\\n\\n把\\"审合同\\"这件事做好，传统方案几乎都卡在三个环节：\\n\\n| 难题               | 典型表现                                                                   | 传统解法的痛点                           |\\n| ------------------ | -------------------------------------------------------------------------- | ---------------------------------------- |\\n| **① 关键条款识别** | 几十条条款里，哪些是责任限制、付款、知识产权、数据合规等关键条款？得逐条读 | 纯人工，长合同容易看漏；不同人审标准不一 |\\n| **② 风险标注**     | 责任不设上限、付款条件偏离惯例、IP 全归对方——这些\\"坑\\"怎么系统性地标出来    | 靠法务经验，新人审不出深坑；经验难传承   |\\n| **③ 修改建议**     | 发现风险后，怎么给出既合规又能谈成的条款改写？要引用历史判例和行业范本     | 每次从零写，耗时；历史谈判经验留不下来   |\\n\\nJiuwenSwarm 的解法是：**把合同审查变成一支并行评审的 Agent 团队**——一个审查协调官（Leader）把合同解析后分发给条款提取、风险标注、合规校验三个 Agent 并行评审，再由修改建议 Agent 整合输出条款级改写；每审完一份，新发现的\\"坑\\"自动沉淀进条款库 `TEAM_MEMORY.md`，下一份合同自动参考。\\n\\n---\\n\\n## JiuwenSwarm 凭什么能“审合同”\\n\\n**JiuwenSwarm** 是一款让多智能体真正协作起来的 Agent 系统，帮助用户通过自然语言驱动多 Agent 协作、Skill 自演进和工具调用，实现从意图到结果的端到端交付。\\n\\n落到合同审查场景，本文会用到这几项能力：\\n\\n- **Swarmflow（蜂群流）**：把\\"审这份合同\\"自动拆成解析 → 并行评审（条款提取/风险标注/合规校验同时跑）→ 汇总 → 生成建议的可执行工作流，高风险条款触发条件分支走人工复核。\\n- **Agent Team + TeamSkill**：声明式定义审查团队的四个角色，三路并行评审是天然适合 `parallel` 原语的场景。\\n- **双层团队记忆**：条款库——每审一份合同，新发现的苛刻条款、谈判策略沉淀为 `[lesson]`/`[decision]`，跨合同累积，越审越懂甲乙双方的套路。\\n- **工具权限与安全防护**：高风险条款（如无上限责任）标记后触发 `ask`，必须法务人工确认才放行。\\n\\n> 一句话理解：JiuwenSwarm 不是\\"再写一个合同关键词检索工具\\"，而是把审查协作从 **\\"靠人逐条看\\"** 变成 **\\"并行评审 + 经验沉淀 + 越审越准\\"**。\\n\\n---\\n\\n## 并行评审的合同审查团队\\n\\n先看全貌。下图把合同审查映射成了三层：\\n\\n![合同智能审查总体架构](./assets/arch-overview.png)\\n\\n- **顶层 · 蜂群协作层（合同审查 Team）**：一个 Leader（审查协调官）+ 四个专业 Teammate（条款提取 / 风险标注 / 合规校验 / 修改建议），其中前三个**并行评审**，最后由修改建议 Agent 整合。\\n- **中层 · 条款库 TEAM_MEMORY.md**：跨合同累积的审查经验，所有成员只读。这是\\"越审越准\\"的核心。\\n- **底层 · 文档输入层**：合同 PDF/扫描件（OCR 解析）、Word 协作稿、历史条款库、法规库/行业范本。\\n\\n注意一个关键设计：**条款提取、风险标注、合规校验三路并行**——它们看的是同一份合同的不同维度，互不依赖，正好适合 `parallel` 原语同时跑。风险标注 Agent 在判定时会去读条款库里\\"这类条款历史怎么处理\\"的 `[lesson]`，而不是从零判断。\\n\\n---\\n\\n## 让关键条款自己浮出来\\n\\n\\"审这份合同\\"这句话，背后是一个有并行/串行/条件分支的工作流：\\n\\n> 解析合同全文 →（条款提取 ‖ 风险标注 ‖ 合规校验 三路并行）→ 风险汇总 →（高风险？律师人工复核）→ 生成修改建议\\n\\nJiuwenSwarm 的 **Swarmflow** 把这套流程写成一段**可执行的 Python**：\\n\\n![合同审查 Swarmflow 流程](./assets/dag-review.png)\\n\\n几个关键点：\\n\\n1. **三路并行评审（parallel）**：T1a 条款提取、T1b 风险标注、T1c 合规校验同时进行——它们彼此独立，并行能把审查时间从\\"逐项串行\\"压缩到\\"最长那一路\\"的时间。\\n2. **风险汇总后分级**：T2 把三路结果合并，按高/中/低分级排序。\\n3. **条件分支 + 人工复核**：若出现高风险条款（如责任不设上限），自动进入 H1 律师人工复核节点——人作为\\"有状态算子\\"确认或改写，复核通过才进入建议生成。\\n\\n### 审查的工作流长什么样\\n\\nSwarmflow 的工作流是一段真实的 Python，基于仓库里 [SwarmSkill 工作流模板](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/swarmskill-creator/templates/scripts/workflow.py.template) 的结构。改成合同审查后：\\n\\n```python\\nfrom swarmflow import agent, compact, log, parallel, phase\\n\\nMETA = {\\n    \\"name\\": \\"contract-review\\",\\n    \\"description\\": \\"合同智能审查：解析→并行评审（条款/风险/合规）→汇总→修改建议\\",\\n    \\"whenToUse\\": \\"用户提供合同文件要求做法律审查、风险排查时复用\\",\\n    \\"phases\\": [\\n        {\\"title\\": \\"解析\\",   \\"detail\\": \\"解析合同全文（PDF/Word/OCR）\\"},\\n        {\\"title\\": \\"评审\\",   \\"detail\\": \\"条款提取、风险标注、合规校验三路并行\\"},\\n        {\\"title\\": \\"汇总\\",   \\"detail\\": \\"合并三路结果，风险分级排序\\"},\\n        {\\"title\\": \\"建议\\",   \\"detail\\": \\"高风险人工复核 → 生成条款级修改建议\\"},\\n    ],\\n}\\n\\nCLAUSE_SCHEMA = {  # 结构化输出\\n    \\"type\\": \\"object\\",\\n    \\"properties\\": {\\"clauses\\": {\\"type\\": \\"array\\"}, \\"risks\\": {\\"type\\": \\"array\\"}, \\"verdict\\": {\\"type\\": \\"string\\"}},\\n}\\n\\nasync def run(args):\\n    # —— 阶段1 解析 ——\\n    phase(\\"解析\\")\\n    full_text = await agent(\\n        build_prompt(\\"解析合同\\", {\\"file\\": args[\\"file\\"]}),\\n        label=\\"解析\\", phase=\\"解析\\", schema={\\"type\\": \\"object\\", \\"properties\\": {\\"text\\": {\\"type\\": \\"string\\"}}},\\n    )\\n\\n    # —— 阶段2 评审：三路并行 ——\\n    phase(\\"评审\\")\\n    review = await parallel([\\n        lambda: agent(build_prompt(\\"条款提取\\", full_text),\\n                      label=\\"条款提取\\", phase=\\"评审\\", schema=CLAUSE_SCHEMA),\\n        lambda: agent(build_prompt(\\"风险标注\\", full_text),\\n                      label=\\"风险标注\\", phase=\\"评审\\", schema=CLAUSE_SCHEMA),\\n        lambda: agent(build_prompt(\\"合规校验\\", full_text),\\n                      label=\\"合规校验\\", phase=\\"评审\\", schema=CLAUSE_SCHEMA),\\n    ])\\n    review = compact(review)  # 某一路异常不阻断整体\\n\\n    # —— 阶段3 汇总分级 ——\\n    phase(\\"汇总\\")\\n    summary = await agent(\\n        build_prompt(\\"风险汇总\\", {\\"review\\": review, **args}),\\n        label=\\"汇总\\", phase=\\"汇总\\", schema={\\"type\\": \\"object\\", \\"properties\\": {\\"risks\\": {\\"type\\": \\"array\\"}}},\\n    )\\n    risks = extract_json(summary).get(\\"risks\\", [])\\n\\n    # —— 阶段4 高风险复核 + 修改建议 ——\\n    phase(\\"建议\\")\\n    high_risks = [r for r in risks if r.get(\\"level\\") == \\"high\\"]\\n    if high_risks:\\n        log(f\\"发现 {len(high_risks)} 个高风险条款 → 进入律师人工复核\\")\\n        review_result = await agent(build_prompt(\\"高风险复核\\", {\\"risks\\": high_risks}),\\n                                    label=\\"复核\\", phase=\\"建议\\", schema={\\"type\\": \\"object\\"})\\n        if extract_json(review_result).get(\\"verdict\\") == \\"驳回\\":\\n            return {\\"status\\": \\"degraded\\", \\"reason\\": \\"高风险条款需重新谈判\\"}\\n\\n    suggestions = await agent(\\n        build_prompt(\\"生成修改建议\\", {\\"risks\\": risks, \\"review\\": review}),\\n        label=\\"建议\\", phase=\\"建议\\", schema={\\"type\\": \\"object\\", \\"properties\\": {\\"suggestions\\": {\\"type\\": \\"array\\"}}},\\n    )\\n    return {\\"status\\": \\"complete\\", \\"risks\\": risks, \\"suggestions\\": extract_json(suggestions).get(\\"suggestions\\")}\\n```\\n\\n![](assets/image-20260714200405991.png)\\n\\n\\n\\n这段代码的核心是 `parallel([...])` 把三路评审同时拉起，`compact([...])` 保证任一路失败不阻断。工作流跑起来后持续吐进度事件（`workflow_started → phase → agent_started → agent_completed → …`），事件派发表见仓库 [`workflow_state.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/team/handlers/workflow_state.py)。\\n\\n> 过去要法务逐条看完一份合同才能下结论，现在三路并行评审 + 高风险自动拦截，**审查效率和覆盖面都上了一个台阶**。\\n\\n---\\n\\n## 风险怎么标注、怎么分级\\n\\n风险标注不是\\"拍脑袋\\"，而是**多源融合判定**。风险标注 Agent 在判断一个条款是否有风险时，会综合三个来源：\\n\\n![合同风险标注矩阵](./assets/risk-matrix.png)\\n\\n- **条款库（TEAM_MEMORY.md）**：历史审合同沉淀的 `[lesson]`——比如\\"无上限责任条款近 12 份合同谈判均被否，标准策略是上限取合同额 1 倍 + 排除间接损失\\"。命中已知坑直接判高风险。\\n- **法规强制条款**：违反法律法规的强制规定（如缺失个人信息处理条款违反个保法），直接判高风险。\\n- **行业范本/谈判惯例**：偏离行业惯例（如预付款惯例 ≤30%、账期 ≥45 天），判中风险。\\n\\n判定逻辑落到权限体系上，就是分级处理：\\n\\n| 风险等级    | 处理方式                                                 |\\n| ----------- | -------------------------------------------------------- |\\n| **高风险**  | 触发 H1 律师人工复核（对应权限的 `ask`），必须确认或改写 |\\n| **中风险**  | 由修改建议 Agent 给出改写方向，提示但不强制              |\\n| **低/正常** | 自动放行（对应权限的 `allow`）                           |\\n\\n团队记忆的写入机制和餐饮篇一致：在 `lifecycle: persistent` 的团队里，**Leader 每轮结束派一个提取 Agent**，把本轮新发现的\\"坑\\"蒸馏成 `[lesson]`/`[decision]`/`[context]` 写入条款库，文件自动保持在 200 行以内（旧的合并/淘汰）。这意味着**第 100 份合同审完，前 99 份的经验都在条款库里**。\\n\\n记忆写入用的是仓库的 [`memory_tools.py`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/common/tools/memory_tools.py)（`write_memory` 工具，路径校验只允许 `memory/*.md`，且群聊模式下禁用写入防污染）。\\n\\n---\\n\\n## 修改建议是怎么生成的\\n\\n合同审查团队用 **TeamSkill（团队技能）** 标准定义，和餐饮采购团队一样是五文件结构（[`/teamskills validate`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/TeamSkills.md) 硬校验）：\\n\\n```\\ncontract-review-team/\\n├── SKILL.md              # kind: team-skill + roles[] 四角色\\n├── roles/\\n│   ├── clause-extractor.md     # 条款提取\\n│   ├── risk-auditor.md         # 风险标注\\n│   ├── compliance-checker.md   # 合规校验\\n│   └── suggestion-writer.md    # 修改建议\\n├── workflow.md           # 协作流程（mermaid + 质量门控）\\n├── bind.md               # 并发/预算/失败兜底\\n└── dependencies.yaml     # skills + tools 声明\\n```\\n\\n`SKILL.md` frontmatter（基于仓库 [`medical-consultation-team`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/TeamSkills.md) 范例结构）：\\n\\n```markdown\\n---\\nname: contract-review-team\\nversion: 1.0.0\\ndescription: |\\n  合同智能审查团队，协调官组织条款提取、风险标注、合规校验并行评审并整合修改建议。\\n  Use when 需要对合同做法律风险审查、关键条款排查、修改建议生成。\\n  Do NOT use for 合同商务条款的非法律性谈判策略制定。\\nkind: team-skill\\nroles:\\n  - id: coordinator\\n    purpose: 解析合同、分发条款、汇总风险、高风险人工复核\\n    skills: []\\n    tools: [send_message, create_task, read_file]\\n  - id: clause-extractor\\n    purpose: 结构化提取关键条款（付款/违约/IP/保密/终止等）\\n    skills: [financial-document-parser]\\n    tools: []\\n  - id: risk-auditor\\n    purpose: 对照条款库+法规，对条款做高/中/低风险分级标注\\n    skills: []\\n    tools: [memory_search, mcp_paid_search]\\n  - id: compliance-checker\\n    purpose: 数据合规/反垄断/行业监管红线检查\\n    skills: []\\n    tools: [mcp_paid_search]\\n  - id: suggestion-writer\\n    purpose: 生成条款级修改建议文本，引用历史判例/范本\\n    skills: []\\n    tools: [write_file]\\n---\\n```\\n\\n每个 `roles/<id>.md` 文件同样有 5 个必填段落，其中 `## Identity` 的座右铭是防趋同的关键：\\n\\n- 风险标注 Agent：`> *\\"我对任何\'看起来合理\'的条款都保持警惕，宁可误报也不漏报。\\"*`\\n- 合规校验 Agent：`> *\\"我只认法规红线，行业惯例在我这里不构成豁免理由。\\"*`\\n\\n`## Boundary` 里的 `**Forbidden**`/`**Mandatory**` 防止角色越界：风险标注 Agent 被 Forbidden 改写条款（那是 suggestion-writer 的活），合规校验 Agent 被 Forbidden 碰商务条款判断。\\n\\n> 这里用到的 `mcp_paid_search`、`memory_search`、`read_file`、`write_file` 都是仓库 [`harness/common/tools/`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/agents/harness/common/tools/) 里真实注册的工具：`mcp_paid_search` 做法规检索、`memory_search`（语义+BM25 混合检索）查条款库、`read_file`/`write_file` 读写合同文件。\\n\\n---\\n\\n## PDF 和扫描件怎么进来\\n\\n合同大多是 PDF 或扫描件，先得把文字\\"抠\\"出来。JiuwenSwarm 仓库内置的 [`financial-document-parser`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/financial-document-parser/SKILL.md) 技能正好能干这事——它用 `pdfplumber` 解析文本 PDF、用 `pytesseract` + `pdf2image` 对扫描件做 OCR 兜底，输出结构化文本：\\n\\n```\\n| 类型 | 格式 | 提取内容 |\\n| 合同 | PDF | 条款全文、签署方、日期、金额 |\\n| 扫描件 | PDF/图片 | OCR 识别全文（兜底） |\\n```\\n\\n在审查团队里，条款提取 Agent（`clause-extractor`）调用这个技能解析合同 PDF，把\\"第八条 责任限制……应全额赔偿包括间接损失\\"这种条款文本抠出来，再喂给风险标注 Agent 判定。OCR 兜底意味着**即使是扫描的纸质合同也能审**。\\n\\n对于结构化条款管理，还可以配合仓库的 [`llm-wiki`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/llm-wiki/SKILL.md) 技能建一个本地的\\"标准条款范本库\\"，新合同自动对照范本找差异。\\n\\n---\\n\\n## 合同审查台长什么样\\n\\n把上述能力拼起来，审一份合同时产出这样的审查台：\\n\\n![](assets/image-20260714200451930.png)\\n\\n\\n\\n![合同智能审查台](./assets/dashboard.png)\\n\\n审查台分三栏，对应本文的核心流程：\\n\\n- **左栏 · 合同原文（风险高亮）**：解析后的合同全文，高风险条款红色高亮（§8 责任不设上限+间接损失、§12 衍生 IP 全归甲方），中风险黄色高亮（§15 预付 60%、§20 保密期 3 年），正常条款绿色标记。\\n- **中栏 · 风险标注清单**：KPI（2 高风险/2 中风险/57 正常）+ 每条风险的详情和修改建议方向。比如 §8 命中条款库 `[lesson]`（无上限责任历史谈判均被否），给出\\"上限取合同额 1 倍+排除间接损失\\"的建议。\\n- **右栏 · 审查 Team 状态 + 条款库记忆**：四个 Agent 的并行评审状态（条款提取 ✓、风险标注 ✓、合规校验 ⚠ 发现缺数据条款、修改建议 ✓），以及当前条款库里沉淀的 `[lesson]`/`[decision]`/`[context]`——正是这些经验让审查能\\"越审越准\\"。\\n\\n> 这份审查台背后：合同上传后自动解析，三路 Agent 并行评审，高风险自动拦截待律师确认，修改建议引用条款库历史经验——**审查、标注、建议、经验沉淀一条龙**。\\n\\n---\\n\\n## 落地建议与总结\\n\\n如果你也想在自家法务/合规团队上落地，建议按这个节奏来：\\n\\n1. **先跑通单类合同**：选一类高频合同（如采购合同），1 个 Leader + 3 个评审 Teammate，手动触发验证 Swarmflow DAG 和并行评审逻辑。\\n2. **积累条款库**：团队设 `lifecycle: persistent`，把过去审过的合同的\\"坑\\"和谈判策略沉淀进 `TEAM_MEMORY.md`，跑一个月后条款库就有足够经验支撑自动判定。\\n3. **配好风险分级策略**：高风险条款（无上限责任、IP 全归对方、违约金畸高）用条件分支强制走律师复核；中低风险自动出建议。\\n4. **接入 OCR + 法规检索**：用 `financial-document-parser` 处理扫描件，`mcp_paid_search` 做实时法规检索，保证审查依据的时效性。\\n\\n### 三句话总结\\n\\n- **关键条款识别**：Swarmflow 把审查变成并行 DAG，条款提取/风险标注/合规校验三路同时跑，几十条条款几分钟扫完。\\n- **风险标注**：条款库记忆 + 法规 + 行业范本三源融合判定，高风险自动拦截待律师确认，每审一份合同条款库就厚一层。\\n- **修改建议**：修改建议 Agent 基于条款库历史经验生成条款级改写，引用判例和范本，新人也能产出老法务水平的审查意见。\\n\\n随着 Agent 协同在法务合规场景深入，**\\"经验沉淀 + 并行评审 + 自动建议\\"的合同审查模式将大幅提升法务效率与风险覆盖面**——而 JiuwenSwarm 让这条路触手可及。\\n\\n---\\n\\n## 相关引用\\n\\n1. JiuwenSwarm 官网：<https://openjiuwen.com>\\n2. JiuwenSwarm 仓库（GitCode）：<https://gitcode.com/openJiuwen/jiuwenswarm>\\n3. 官方文档：\\n   - [TeamSkill 团队技能指南](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/TeamSkills.md)\\n   - [Agent Team 使用指南](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/AgentTeam.md)\\n   - [记忆系统](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/记忆.md)\\n   - [工具权限与安全防护](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/docs/zh/工具权限与安全防护.md)\\n4. 相关技能：[`financial-document-parser`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/financial-document-parser/SKILL.md)、[`llm-wiki`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/llm-wiki/SKILL.md)、[`openJiuwen-DeepSearch`](https://gitcode.com/openJiuwen/jiuwenswarm/blob/develop/jiuwenswarm/resources/agent/workspace/skills/openJiuwen-DeepSearch/SKILL.md)\\n"}'),E={name:"AI人工智能/jiuwenswarm-垂直行业技术文章/03-法律合规场景/合同智能审查与风险追踪：关键条款识别+风险标注+修改建议.md"};function d(g,s,c,u,m,y){return a(),n("div",null,[...s[0]||(s[0]=[e("",79)])])}const w=i(E,[["render",d]]);export{b as __pageData,w as default};
